import unittest
from src.app import stock_total

class TotalTests(unittest.TestCase):
    def test_ignores_negative_quantities(self):
        self.assertEqual(stock_total([{'quantity': -7}, {'quantity': 2}, {'quantity': 0}, {'quantity': 4}]), 6)

