import unittest
from src.app import empty_message, stock_total

class InventoryTests(unittest.TestCase):
    def test_empty_message(self):
        self.assertEqual(empty_message(), 'No items saved.')

    def test_empty_total(self):
        self.assertEqual(stock_total([]), 0)

    def test_positive_total(self):
        self.assertEqual(stock_total([{'quantity': 2}, {'quantity': 4}]), 6)
